  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Trazodone, a high-transfer analogue, has oral bioavailability of 65% in healthy subjects after a single 100 mg dose, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Alprazolam, a high-transfer triazolobenzodiazepine, has absolute oral bioavailability of 0.92 in humans, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Triazolam, a close structural analogue, has mean oral bioavailability of 55.1% with a range of 22.4-116% in healthy subjects, all above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Flibanserin, despite lower absorption, has absolute oral bioavailability of 45.9% in volunteers, still well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Tolfenamic acid has absolute oral bioavailability averaging 60% in healthy volunteers across multiple doses, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Netupitant has high absolute oral bioavailability of 63-87% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Eltrombopag has estimated oral bioavailability of at least 52% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Meclofenamate has human oral bioavailability above 85%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well above 20%, mostly in the 33-100% range. The query, aminopyrine, is a small lipophilic pyrazolone with favorable absorption characteristics, so F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for aminopyrine itself is present in the supplied evidence; the prediction relies on high-transfer analogues.",
    "Some analogues such as flibanserin and triazolam have moderate F values (33-60%), but all remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

